import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"Rclone S3 Timestamp Module","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/modules/rclone-s3-timestamp.md","filePath":"en/deep-dive/modules/rclone-s3-timestamp.md","lastUpdated":1794234466000}`),a={name:`deep-dive/modules/rclone-s3-timestamp.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="rclone-s3-timestamp-module" tabindex="-1">Rclone S3 Timestamp Module <a class="header-anchor" href="#rclone-s3-timestamp-module" aria-label="Permalink to “Rclone S3 Timestamp Module”">​</a></h1><p>This module preserves file modification times when Sync Engine uses the S3 backend with <a href="https://rclone.org/commands/rclone_serve_s3/" target="_blank" rel="noreferrer"><code>rclone serve s3</code></a>. It applies automatically when the S3 backend is selected.</p><h2 id="modification-time" tabindex="-1">Modification Time <a class="header-anchor" href="#modification-time" aria-label="Permalink to “Modification Time”">​</a></h2><p>Sync Engine stores <code>mtime</code> in milliseconds, while rclone interprets <code>x-amz-meta-mtime</code> as Unix seconds. The module converts the header on the wire, in both directions: uploads convert milliseconds to seconds (for example, <code>1700000123456</code> to <code>1700000123.456</code>), and downloads convert seconds back to milliseconds.</p><p>Conversion applies only to parsable values: uploads convert only values shaped like Sync Engine timestamps (13-digit milliseconds); downloads convert only numeric values. When <code>rclone serve s3</code> loses its in-memory metadata after a server restart and omits <code>x-amz-meta-mtime</code>, the S3 backend recovers the time from <code>Last-Modified</code> on its own.</p><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to “Encryption”">​</a></h2><p>When <a href="./encryption">encryption</a> is enabled, its wrapper (priority 7919) encrypts metadata before the S3 backend turns it into <code>x-amz-meta-*</code> headers. The encrypted <code>mtime</code> is non-numeric, so this module leaves it unchanged; encryption restores the millisecond value on read.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><p>The module registers a remote request middleware at priority <code>307</code>, outside the S3 SigV4 middleware (<code>304</code>) so request signatures cover the converted value, and inside the retry middleware (<code>2000</code>) so every attempt converts from the original parameters. The middleware rebuilds requests and responses instead of mutating them, leaving every other header untouched.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};